// F — relatório semanal de oportunidades, em português.
const envelope=$input.first().json||{};
const data=envelope.data||{}, all=[...(data.vagas||[]),...(data.historicoVagas||[])];
const events=Array.isArray(data.eventosHistorico)?data.eventosHistorico:[];
const reports=Array.isArray(envelope.reportsArchive?.reports)?envelope.reportsArchive.reports:[];
const today=new Date();
const monday=new Date(Date.UTC(today.getUTCFullYear(),today.getUTCMonth(),today.getUTCDate()));
monday.setUTCDate(monday.getUTCDate()-(monday.getUTCDay()+6)%7);
const periodStart=new Date(monday.getTime()-7*86400000);
const periodEnd=monday;
const since=periodStart.toISOString(),until=periodEnd.toISOString();
const reportKey=periodStart.toISOString().slice(0,10);
const inWindow=date=>date&&date>=since&&date<until;
const byId=new Map(all.map(j=>[j.id,j]));
const status=j=>j.statusCandidatura||j.application_status||'PENDING_VALIDATION';
const verified=j=>Boolean(j.last_verified_at||j.ultimaVerificacaoCandidatura);
const group=(ids)=>[...new Set(ids)].map(id=>byId.get(id)).filter(Boolean);
const periodEvents=events.filter(e=>inWindow(e.em));
const previousReports=reports.filter(r=>r.weekKey<reportKey);
const previouslyReported=new Set(previousReports.flatMap(r=>r.reportedJobIds||[]));
const inFirstReport=previousReports.length===0;
const newConfirmed=group(periodEvents.filter(e=>e.tipo==='nova').map(e=>e.id))
 .filter(j=>status(j)==='ACTIVE'&&verified(j));
const continuesOpen=all.filter(j=>status(j)==='ACTIVE'&&verified(j)&&
  (previouslyReported.has(j.id)||(inFirstReport&&String(j.first_seen_at||j.primeiraIdentificacao||'')<since)))
 .filter(j=>!newConfirmed.some(x=>x.id===j.id));
const closed=group(periodEvents.filter(e=>e.tipo==='encerrada').map(e=>e.id))
 .filter(j=>['CLOSED','EXPIRED'].includes(status(j)));
const updated=group(periodEvents.filter(e=>e.tipo==='atualizada').map(e=>e.id))
 .filter(j=>!closed.some(x=>x.id===j.id));
const unverified=all.filter(j=>!['ACTIVE','CLOSED','EXPIRED'].includes(status(j)))
 .filter(j=>inWindow(j.last_seen_at||j.ultimaIdentificacao||'')||inWindow(j.last_verified_at||j.ultimaVerificacaoCandidatura||''))
 .sort((a,b)=>Number(b.compatibility_score||0)-Number(a.compatibility_score||0));
const counts={new:newConfirmed.length,continued:continuesOpen.length,closed:closed.length,
 updated:updated.length,unverified:unverified.length};
function label(j){
 return (j.cargo||j.title||'Cargo não informado')+' — '+(j.empresa||j.company||'Empresa não informada')+
  ' | Score: '+(j.compatibility_score??'não calculado')+'/100 | '+(j.local||j.location||'Local não informado')+
  ' | '+(j.link||j.application_url||'Sem link');
}
function section(title,jobs,empty){
 return title+' ('+jobs.length+')\n'+(jobs.length?jobs.map((j,i)=>(i+1)+'. '+label(j)).join('\n'):empty);
}
const header='Relatório semanal TecOps — '+reportKey+' a '+new Date(periodEnd.getTime()-86400000).toISOString().slice(0,10);
const noNews='Nenhuma nova vaga confirmada foi encontrada nesta semana.';
const textReport=[header,
 newConfirmed.length?'Foram confirmadas '+newConfirmed.length+' novas oportunidades.':noNews,
 section('Novas oportunidades confirmadas',newConfirmed,noNews),
 section('Oportunidades anteriormente reportadas que continuam abertas',continuesOpen,'Nenhuma oportunidade anterior com abertura confirmada.'),
 section('Oportunidades encerradas',closed,'Nenhum encerramento confirmado nesta semana.'),
 section('Oportunidades atualizadas',updated,'Nenhuma atualização relevante identificada nesta semana.'),
 section('Vagas que não puderam ser verificadas',unverified,'Nenhuma vaga pendente de verificação nesta semana.'),
 'Observações: "continua aberta" requer evidência de candidatura na fonte. Respostas HTTP isoladas ou indisponibilidade não comprovam abertura. Vagas encerradas podem estar fora da lista de 400, mas permanecem no histórico.'
].join('\n\n');
const escape=s=>String(s).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const html='<div style="font-family:Arial,sans-serif;line-height:1.55;color:#1f2937;max-width:760px">'+
 '<h1>'+escape(header)+'</h1><p><strong>'+escape(newConfirmed.length?'Foram confirmadas '+newConfirmed.length+' novas oportunidades.':noNews)+'</strong></p>'+
 [['Novas oportunidades confirmadas',newConfirmed],['Oportunidades anteriores ainda abertas',continuesOpen],
  ['Encerradas',closed],['Atualizadas',updated],['Não verificadas',unverified]].map(([name,jobs])=>
  '<h2>'+escape(name)+' ('+jobs.length+')</h2>'+
  (jobs.length?'<ol>'+jobs.map(j=>'<li>'+escape(j.cargo||j.title||'Sem cargo')+' — '+escape(j.empresa||j.company||'Sem empresa')+
    ' · score '+escape(j.compatibility_score??'n/d')+'/100 · '+escape(j.local||j.location||'Local não informado')+
    (String(j.link||j.application_url||'').startsWith('https://')?' · <a href="'+escape(j.link||j.application_url)+'">Ver anúncio</a>':'')+'</li>').join('')+'</ol>':'<p>Sem ocorrências.</p>')).join('')+
 '<p><small>Disponibilidade estimada; confira sempre o anúncio original.</small></p></div>';
const reportedJobIds=[...new Set([...newConfirmed,...continuesOpen,...updated,...unverified,...closed].map(j=>j.id))].sort();
const report={weekKey:reportKey,generatedAt:new Date().toISOString(),since,until,counts,
 reportedJobIds,sections:{new:newConfirmed.map(j=>j.id),continued:continuesOpen.map(j=>j.id),
 closed:closed.map(j=>j.id),updated:updated.map(j=>j.id),unverified:unverified.map(j=>j.id)},
 text:textReport};
return [{json:{...envelope,report,reportText:textReport,reportHtml:html,
 reportSubject:'TecOps — Relatório semanal '+reportKey,
 messageNoNewConfirmed:newConfirmed.length===0}}];
